"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["309"],{602(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>a,contentTitle:()=>r,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"SoftwareEngineering/monolith-vs-microservices","title":"Monolith vs Microservices","description":"The single most consequential architecture decision most teams make \u2014 and one of the most commonly made for the wrong reasons. This page is a decision framework, not a recommendation for either side.","source":"@site/docs/SoftwareEngineering/09-monolith-vs-microservices.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/monolith-vs-microservices","permalink":"/Mindstack/docs/SoftwareEngineering/monolith-vs-microservices","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":9,"frontMatter":{"title":"Monolith vs Microservices","sidebar_label":"Monolith vs Microservices","sidebar_position":9},"sidebar":"softwareEngineeringSidebar","previous":{"title":"API Design","permalink":"/Mindstack/docs/SoftwareEngineering/api-design"},"next":{"title":"Microservices Deep Dive","permalink":"/Mindstack/docs/SoftwareEngineering/microservices-deep-dive"}}'),o=i(4848),s=i(8453);let a={title:"Monolith vs Microservices",sidebar_label:"Monolith vs Microservices",sidebar_position:9},r="Monolith vs Microservices",l={},c=[{value:"What Each Actually Is",id:"what-each-actually-is",level:2},{value:"The Trade-offs, Honestly",id:"the-trade-offs-honestly",level:2},{value:"When a Monolith Is the Right Choice",id:"when-a-monolith-is-the-right-choice",level:2},{value:"When Microservices Are the Right Choice",id:"when-microservices-are-the-right-choice",level:2},{value:"The Most Common Mistake: Premature Microservices",id:"the-most-common-mistake-premature-microservices",level:2},{value:"A Decision Framework",id:"a-decision-framework",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"monolith-vs-microservices",children:"Monolith vs Microservices"})}),"\n",(0,o.jsx)(n.p,{children:"The single most consequential architecture decision most teams make \u2014 and one of the most commonly made for the wrong reasons. This page is a decision framework, not a recommendation for either side."}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"what-each-actually-is",children:"What Each Actually Is"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"MONOLITH\n  One deployable unit. All business logic lives in a single codebase,\n  runs as a single process (or a small number of identical replicas\n  behind a load balancer), typically backed by one database.\n\n        \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n        \u2502                MONOLITH               \u2502\n        \u2502  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510  \u2502\n        \u2502  \u2502  Users  \u2502 \u2502  Orders \u2502 \u2502 Billing \u2502  \u2502\n        \u2502  \u2502  Module \u2502 \u2502  Module \u2502 \u2502  Module \u2502  \u2502\n        \u2502  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518  \u2502\n        \u2502                                       \u2502\n        \u2502              \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510             \u2502\n        \u2502              \u2502 Database \u2502             \u2502\n        \u2502              \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518             \u2502\n        \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nMICROSERVICES\n  Many independently deployable services, each owning a specific\n  business capability and typically its own database, communicating\n  over the network (HTTP, gRPC, message queues).\n\n   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n   \u2502  Users    \u2502   \u2502  Orders   \u2502   \u2502 Billing   \u2502\n   \u2502  Service  \u2502   \u2502  Service  \u2502   \u2502 Service   \u2502\n   \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510  \u2502   \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510  \u2502   \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510  \u2502\n   \u2502 \u2502  DB  \u2502  \u2502   \u2502 \u2502  DB  \u2502  \u2502   \u2502 \u2502  DB  \u2502  \u2502\n   \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518  \u2502   \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518  \u2502   \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518  \u2502\n   \u2514\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2518\n         \u2502  network calls (HTTP/gRPC/queue)\n         \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"the-trade-offs-honestly",children:"The Trade-offs, Honestly"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"                         MONOLITH                  MICROSERVICES\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nInitial complexity       Low                       High\n\nDevelopment speed\n  Small team / early     Fast \u2014 little            Slower \u2014 infrastructure\n                         infrastructure           and service setup adds\n                         overhead                 overhead\n\n  Large team / mature    Can degrade as the       Can stay fast \u2014 teams\n                         codebase and team        can work independently\n                         grow                     \n\n                         \u2022 Merge conflicts\n                         \u2022 Slow test suites\n                         \u2022 Unclear ownership\n\nScaling                  Scale the WHOLE          Scale EACH service\n                         application, even if     independently based\n                         only one part is         on actual need\n                         under load\n\nTechnology choice        One stack for the        Each service can use\n                         entire application       its own stack\n\nFailure isolation        One bug can potentially  A failing service does\n                         take down the entire     not necessarily take\n                         application              down the others\n\nTesting                  Simpler \u2014 one process    Harder \u2014 network calls,\n                         and in-process calls     more moving parts, and\n                                                  distributed testing\n\nData consistency         Easy \u2014 one database      Hard \u2014 data is spread\n                         and real transactions    across services\n                                                 \n                                                  See: Saga pattern\n                                                  (File 10)\n\nOperational overhead     Low \u2014 one thing to       High \u2014 many services\n                         monitor, deploy,         to monitor, deploy,\n                         and debug                and debug\n\n                                                  See: DevOps course\n\nDeployment               Simple \u2014 deploy one      More complex \u2014 many\n                         unit                     services require\n                                                  orchestration\n\n                                                  See: DevOps course\n"})}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"The uncomfortable truth: microservices trade development-time complexity for organizational scalability \u2014 and that trade is only worth making once you actually have the organizational complexity to justify it."})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"when-a-monolith-is-the-right-choice",children:"When a Monolith Is the Right Choice"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Small team (roughly under 10-15 engineers)\n  Communication overhead of coordinating across service boundaries\n  exceeds any benefit \u2014 a small team can coordinate a monolith's\n  internal module boundaries through simple conversation and code review.\n\nEarly-stage product, requirements still shifting significantly\n  Microservice boundaries encode assumptions about where the natural\n  seams in your domain are. Getting those boundaries wrong EARLY, before\n  you understand the domain well, is expensive to fix \u2014 a wrong module\n  boundary inside a monolith is a much cheaper mistake to correct\n  (see file 11, Modular Monolith).\n\nSimple, well-understood domain\n  If the business logic genuinely doesn't have many independent moving\n  parts, splitting it into services adds real operational cost\n  (deployment pipelines, service discovery, distributed tracing \u2014 see\n  the DevOps course) without a matching benefit.\n\nLimited operational maturity/tooling\n  Running microservices well requires container orchestration,\n  centralized logging, distributed tracing, service mesh or API\n  gateway, and a mature CI/CD pipeline (all covered in the DevOps\n  course). Adopting microservices before this tooling and expertise\n  exists trades one set of problems for a worse set.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"when-microservices-are-the-right-choice",children:"When Microservices Are the Right Choice"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Large engineering organization (many independent teams)\n  Team boundaries and service boundaries want to align (this maps\n  directly onto Bounded Contexts from file 07, Domain-Driven Design).\n  Independent deployability means Team A can ship without coordinating\n  a release with Team B.\n\nGenuinely different scaling needs across parts of the system\n  If your image-processing pipeline needs 50 replicas under load but\n  your admin dashboard needs 2, a monolith forces you to scale BOTH\n  together. Microservices let you scale exactly the part that needs it.\n\nNeed for technology diversity\n  A team doing heavy numerical/ML work might genuinely benefit from\n  Python; a latency-critical service might genuinely benefit from Go\n  or Rust. A monolith locks the whole system into one stack.\n\nGenuine need for independent fault isolation\n  If a non-critical feature (say, a recommendation engine) failing\n  should NOT take down checkout, that isolation is much easier to\n  guarantee with separate services than with careful internal monolith\n  discipline alone.\n\nRegulatory/compliance boundaries\n  Sometimes data or processing genuinely needs to be isolated (PCI\n  compliance scope, data residency requirements) \u2014 a separate service\n  with its own clear boundary can make compliance auditing far simpler\n  than proving isolation within a shared codebase.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"the-most-common-mistake-premature-microservices",children:"The Most Common Mistake: Premature Microservices"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"The industry has a well-documented pattern: a small team, excited by\nwhat Netflix/Amazon/Uber do at their scale, adopts microservices for\na product with a handful of users and three engineers.\n\nThe result, almost every time:\n  Massively increased operational burden (each service needs its own\n  deployment pipeline, monitoring, logging \u2014 see the DevOps course)\n  for a system simple enough to run as one process\n  Network calls introduce latency and failure modes (see file 17,\n  CAP theorem) that didn't exist when it was just in-process function calls\n  Debugging a request that flows through 6 services requires\n  distributed tracing infrastructure the team hasn't built yet\n  The TEAM is 3 people \u2014 there's no organizational boundary problem\n  microservices were meant to solve in the first place\n\nThe pattern that actually reflects how most successful microservice\nsystems came to be: START as a well-organized monolith (see file 11),\nand extract services LATER, specifically at the seams that turn out\nto have genuine independent scaling, team ownership, or failure\nisolation needs \u2014 informed by real operational experience, not guessed\nupfront.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"a-decision-framework",children:"A Decision Framework"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'Ask these questions, in this order:\n\n1. How many engineers will work on this system?\n   Under ~10-15: strong default toward a (well-organized) monolith.\n   Many independent teams: microservices become more attractive.\n\n2. Do different parts of the system have genuinely different scaling\n   or reliability needs?\n   No: a monolith can scale as a whole; simpler.\n   Yes, significantly: a specific factor favoring splitting THOSE parts out.\n\n3. Does your team have the operational maturity to run distributed\n   systems well RIGHT NOW?\n   (Container orchestration, centralized logging, distributed tracing,\n   CI/CD maturity \u2014 see the DevOps course for what this actually requires.)\n   No: build that maturity, or stay monolithic until you have it.\n   Yes: microservices become operationally viable.\n\n4. Do you understand the domain well enough to draw good service\n   boundaries?\n   Early-stage/unclear: wrong boundaries are expensive to fix across\n   service boundaries; stay monolithic until boundaries stabilize.\n   Well-understood, stable domain: boundaries are more likely to be\n   drawn correctly from the start.\n\nIf the honest answers mostly point toward "not yet" \u2014 build a modular\nmonolith (file 11) with clean internal boundaries. You retain the\nOPTION to extract services later, at the seams that turn out to\nactually need it, informed by real usage instead of a guess made on\nday one.\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"If you're unsure, default to a monolith \u2014 a well-organized monolith is a genuinely good architecture for most systems, not just a stepping stone; plenty of successful, large-scale products run as monoliths indefinitely."}),"\n",(0,o.jsx)(n.li,{children:'The organizational question ("how many independent teams need to ship independently?") is usually more decisive than the technical question ("could this scale better as services?") \u2014 Conway\'s Law (systems mirror the communication structure of the organizations that build them) is empirically well-supported.'}),"\n",(0,o.jsx)(n.li,{children:"If you do go with microservices, invest in the DevOps foundations FIRST \u2014 container orchestration, centralized logging, distributed tracing \u2014 rather than bolting them on after services are already in production and painful to debug."}),"\n",(0,o.jsx)(n.li,{children:"Reversibility matters: starting monolithic and extracting services later (file 11) is a well-trodden, low-risk path; starting with microservices and merging back into a monolith is rare and painful. When uncertain, prefer the more reversible choice."}),"\n"]}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"A monolith is one deployable unit with typically one database; microservices are many independently deployable services, each usually owning its own data."}),"\n",(0,o.jsx)(n.li,{children:"Microservices trade development-time simplicity for organizational scalability \u2014 that trade is only worth making once you have real organizational complexity (many independent teams) to justify it."}),"\n",(0,o.jsx)(n.li,{children:"Monoliths fit small teams, early-stage/shifting requirements, simple domains, and teams without mature distributed-systems operational tooling."}),"\n",(0,o.jsx)(n.li,{children:"Microservices fit large organizations needing independent deployability, genuinely different per-component scaling needs, technology diversity, or strict fault/compliance isolation."}),"\n",(0,o.jsx)(n.li,{children:"The most common real-world mistake is adopting microservices prematurely, before the organizational or operational need actually exists \u2014 paying real complexity cost for a benefit not yet needed."}),"\n",(0,o.jsx)(n.li,{children:"When uncertain, default to a well-organized (modular) monolith \u2014 see file 11 \u2014 and extract services later, at seams informed by real operational experience."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>r});var t=i(6540);let o={},s=t.createContext(o);function a(e){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);